"""Render MODEL-CARDS.md from the registry and stored evaluations (numbers are never typed by hand)."""
from __future__ import annotations

from sqlalchemy import func, select

from . import modeling as M
from .db import Game, ModelEvaluation, ModelVersion, PlayerBox, session_scope


def _f(x, d=3):
    return "—" if x is None else f"{x:.{d}f}"


def render() -> str:
    out = ["# Model cards", "",
           "_Generated by `gizer model-cards` from the model registry and stored evaluation rows. Do not edit numbers by hand._", ""]
    with session_scope() as s:
        cov = s.execute(select(Game.season, func.count(), func.count(Game.box_ingested_at), func.min(Game.game_date),
                               func.max(Game.game_date)).where(Game.status == "final").group_by(Game.season).order_by(Game.season)).all()
        rows = s.scalar(select(func.count()).select_from(PlayerBox))
        out += ["## Data behind these results", "", "| Season | Final games | With box score | First | Last |", "|---|---|---|---|---|"]
        out += [f"| {c[0]} | {c[1]} | {c[2]} | {c[3]} | {c[4]} |" for c in cov]
        out += ["", f"Player-game rows: {rows}. Regular season only. No historical odds are held, so nothing below is a "
                "market backtest.", "",
                "## Validation protocol", "",
                "Chronological split by date: first 55% training, next 20% calibration, last 25% final evaluation. No random "
                "splits. Features for a game use only earlier dates (shift-by-one construction, tested). Dispersion and "
                "residual scales are fitted on the calibration period only and scored on the evaluation period.", "",
                "Promotion gate (applied by the Chief Model Auditor, never by the author): "
                f"`{M.GATE}`", ""]
        for mv in s.scalars(select(ModelVersion).order_by(ModelVersion.family, ModelVersion.id)):
            ev = M.latest_evaluation(s, mv.id)
            out += [f"## `{mv.family}` — {mv.name} {mv.version}", "",
                    f"* **Status:** {mv.status}" + (f" (promoted by {mv.promoted_by})" if mv.promoted_by else " — not promoted; this family produces no qualified selections"),
                    f"* **Author:** {mv.created_by}",
                    f"* **Training / calibration / evaluation periods:** {mv.training_period} / {mv.calibration_period} / {mv.evaluation_period}",
                    f"* **Applicable markets:** " + ("spread, total, moneyline" if mv.family == "team_game" else f"player {mv.family.split('_')[1]} over/under"),
                    f"* **Parameters:** `{ {k: (round(v, 4) if isinstance(v, float) else v) for k, v in mv.params.items()} }`",
                    f"* **Known limitations:** {mv.limitations}", ""]
            if ev is None:
                out += ["No evaluation stored.", ""]
                continue
            m = ev.metrics
            out += [f"Evaluation #{ev.id}: n = {ev.n_obs}, gate **{'PASSED' if ev.passed else 'FAILED'}** — checks: "
                    + ", ".join(f"{k} {'✓' if v else '✗'}" for k, v in m["gate_checks"].items()), ""]
            if mv.family == "team_game":
                out += ["| Metric | Model | Baseline |", "|---|---|---|",
                        f"| Margin MAE | {_f(m['margin_mae'], 2)} | {_f(m['margin_mae_baseline'], 2)} (home-court constant) |",
                        f"| Total MAE | {_f(m['total_mae'], 2)} | {_f(m['total_mae_baseline'], 2)} (historical mean) |",
                        f"| Home-win Brier | {_f(m['home_win_brier'], 4)} | {_f(m['home_win_brier_baseline'], 4)} (constant rate) |",
                        f"| Home-win accuracy | {_f(m['home_win_accuracy'])} | — |",
                        f"| Total 80% interval coverage | {_f(m['total_coverage_80'])} | nominal 0.80 |",
                        f"| Calibration error (ECE) | {_f(m['ece'], 4)} | — |", "", m["calibration_note"] + ".", ""]
            else:
                out += ["| Model | MAE | RMSE | Bias |", "|---|---|---|---|"]
                out += [f"| {k} | {_f(v['mae'])} | {_f(v['rmse'])} | {_f(v['bias'])} |" for k, v in m["models"].items()]
                out += ["", f"80% interval coverage {_f(m['coverage_80'])} (model-expected {_f(m.get('coverage_80_expected'))}); "
                        f"Brier {_f(m['brier'], 4)} vs constant baseline {_f(m['brier_baseline_constant'], 4)}; log loss {_f(m['log_loss'], 4)}; "
                        f"ECE {_f(m['ece'], 4)}; dispersion r = {_f(m['dispersion_r'], 2)}.", "", m["pseudo_line_note"] + ".", ""]
            out += ["Calibration (evaluation period):", "", "| Predicted bin | n | Mean predicted | Observed | 95% CI |", "|---|---|---|---|---|"]
            out += [f"| {r['lo']:.1f}–{r['hi']:.1f} | {r['n']} | {_f(r['predicted'])} | {_f(r['observed'])} | "
                    + (f"{r['ci'][0]:.3f}–{r['ci'][1]:.3f}" if r["ci"] else "—") + " |" for r in m["calibration"] if r["n"]]
            out.append("")
        ce = s.scalar(select(ModelEvaluation).where(ModelEvaluation.kind == "correlation").order_by(ModelEvaluation.id.desc()).limit(1))
        if ce:
            m = ce.metrics
            out += ["## Correlation engine — gaussian_copula_empirical_v1", "",
                    f"Estimated on {m['period']} from {m['n_team_games']} team-games of standardised forecast residuals. "
                    "Marginal leg probabilities are preserved exactly; only dependence comes from the copula.", "",
                    "| Pair | ρ |", "|---|---|"]
            out += [f"| same player {k.replace('|', ' / ')} | {v:+.3f} |" for k, v in m["same_player"].items()]
            out += [f"| teammates {k.replace('|', ' / ')} | {v:+.3f} |" for k, v in m["teammate"].items()]
            out += [f"| player {k} vs own team points | {v:+.3f} |" for k, v in m["own_team"].items()]
            out += [f"| home vs away team points | {m['team_home_away']:+.3f} |", "",
                    "Joint-frequency validation on the later period (both events occur):", "",
                    "| Pair | n | Observed | Independence | Copula |", "|---|---|---|---|---|"]
            out += [f"| {r['pair']} | {r['n']} | {_f(r['observed'])} | {_f(r['independence'])} | {_f(r['copula'])} |" for r in m["validation"]["rows"]]
            v = m["validation"]
            out += ["", f"Total absolute error: copula {_f(v['abs_error_copula'], 4)} vs independence {_f(v['abs_error_independence'], 4)}.", ""]
            out += ["Limitations: " + " ".join(m["notes"]) + " Teammate correlations are pooled averages and understate "
                    "specific substitution effects (for example a star's absence). Simulation frequency is not a validated "
                    "real-world probability.", ""]
    out += ["## What these results do and do not show", "",
            "* They show how the models forecast outcomes relative to simple baselines on later, unseen dates.",
            "* They do **not** show an advantage over sportsbook prices. That requires historical or forward market data; "
            "forward paper testing is the only evidence being collected.",
            "* Several model variants were evaluated on the same data (baselines, challenger); the evaluation period is "
            "therefore not a pristine holdout for future model selection. Future promotions should be judged on data after "
            "the dates above.", ""]
    return "\n".join(out)
